basicCode.vanilla:
import { createComposer } from '@/components/ui/composer';
import { MENTION_TRIGGER } from '@shared/primitives/composer-trigger';

createComposer({
  labels,
  triggerLabels,
  triggers: [{ spec: MENTION_TRIGGER, options: pessoas }],
});

basicCode.react:
import { Composer } from "@/components/ui/composer";
import { MENTION_TRIGGER } from "@shared/primitives/composer-trigger";

<Composer
  labels={labels}
  triggerLabels={triggerLabels}
  triggers={[{ spec: MENTION_TRIGGER, options: pessoas }]}
/>

withCommandsCode.web:
// O comando vale só no começo do campo, e o que se escreve não é o que
// se lê: o rótulo diz "Resumir a conversa" e o valor escreve "/resumir".
{ spec: COMMAND_TRIGGER, options: [
  { id: 'resumir', label: 'Resumir a conversa', value: '/resumir', hint: '/resumir' },
] }

extensibilityCode.web:
// A opção é dado, e o que ela escreve pode diferir do que ela mostra.
{ id: 'ana', label: 'Ana Souza', hint: 'Produto' }
// escreve "@Ana Souza"

{ id: 'resumir', label: 'Resumir a conversa', value: '/resumir' }
// escreve "/resumir"

customizationCode.web:
.nds-composer-trigger-popover {
  max-block-size: 20rem;
}

/* A opção ativa marca fundo E estado: um é o que os olhos veem, o outro é o
   que o leitor de tela anuncia. */
.nds-composer-trigger-option[aria-selected="true"] {
  background-color: hsl(var(--accent));
}

